 rows=[('Typed decisions',t['metrics']['accuracy'],t['jev_reference']['accuracy'],'2,000 decisions','Aggregate / unpaired'),('PhishNChips',p['metrics']['accuracy'],p['jev_reference']['accuracy'],'2,000 emails','Aggregate / unpaired'),('JevBench public',j['metrics']['jev48_accuracy'],j['metrics']['jev_accuracy'],'231 tasks','Paired outcomes'),('BTZSC pilot',b['metrics']['jev48_accuracy'],b['metrics']['jev_accuracy'],'300 texts','Aggregate / unpaired'),('Code review',c['metrics']['jev48_accuracy'],c['metrics']['jev_accuracy'],'480 rule decisions','Repeated Jev reference'),('CLASH conflicts',x['metrics']['jev48_accuracy'],x['metrics']['jev_accuracy'],'1,289 cases','Aggregate / unpaired')]
